function.arguments:
{"sql": "SELECT COUNT(*) as total_days, COUNT(DISTINCT CONCAT(year, '-', mo, '-', da)) as distinct_days
FROM (
  SELECT stn, wban, year, mo, da, SAFE_CAST(wdsp AS FLOAT64) as wdsp
  FROM `bigquery-public-data.noaa_gsod.gsod*`
  WHERE stn = '744860' AND _TABLE_SUFFIX BETWEEN '2011' AND '2020'
)"}
